\documentclass[tikz,border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{ctex}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    width=12cm,
    height=8cm,
    title={\textbf{2017-2024年中国高考报名人数变化趋势}},
    xlabel={年份},
    ylabel={报名人数（万人）},
    xmin=2016.5, xmax=2024.5,
    ymin=900, ymax=1400,
    xtick={2017,2018,2019,2020,2021,2022,2023,2024},
    xticklabels={2017,2018,2019,2020,2021,2022,2023,2024},
    ytick={900,1000,1100,1200,1300,1400},
    grid=both,
    grid style={dashed, gray!30},
    legend style={
        at={(1.03,0.5)}, 
        anchor=west, 
        draw=black, 
        fill=white,
        font=\small
    },
    nodes near coords style={font=\tiny, anchor=south},
    every axis plot/.append style={line width=2pt},
    axis line style={black},
]

% 高考报名人数数据
\addplot+[
    mark=*,
    mark options={scale=1.5},
    mark size=3pt,
    color=blue!60!black,
    nodes near coords,
    point meta=explicit symbolic
] 
coordinates {
    (2017,940) [940万]
    (2018,975) [975万]
    (2019,1031) [1031万]
    (2020,1071) [1071万]
    (2021,1078) [1078万]
    (2022,1193) [1193万]
    (2023,1291) [1291万]
    (2024,1342) [1342万]
};

\legend{高考报名人数}

% 数据来源注记（写在axis内部）
\node[anchor=north west, font=\scriptsize] at (axis description cs:0.0,-0.12) {数据来源：教育部及各省教育考试院公开数据};

% 趋势说明
\node[anchor=north east, font=\scriptsize] at (axis description cs:1.0,-0.12) {数据来源说明：2017-2024年};

\end{axis}
\end{tikzpicture}

